import http from "node:http";
import { listInvoices, invoiceTotal, exportableInvoices, invoicesToCsv } from "./invoices.js";

export function createServer(invoices = [], { now = () => new Date() } = {}) {
  return http.createServer((req, res) => {
    const url = new URL(req.url, "http://localhost");
    if (req.method !== "GET") {
      res.writeHead(404).end();
      return;
    }
    if (url.pathname === "/invoices" || url.pathname === "/invoices/export.csv") {
      const orgId = req.headers["x-org-id"];
      if (!orgId) {
        res.writeHead(401).end();
        return;
      }
      if (url.pathname === "/invoices") {
        const rows = listInvoices(invoices, { orgId }).map((i) => ({ ...i, totalCents: invoiceTotal(i) }));
        res.writeHead(200, { "content-type": "application/json" }).end(JSON.stringify(rows));
        return;
      }
      const csv = invoicesToCsv(exportableInvoices(invoices, { orgId, now: now() }));
      res
        .writeHead(200, {
          "content-type": "text/csv; charset=utf-8",
          "content-disposition": 'attachment; filename="invoices.csv"',
          "cache-control": "no-store",
        })
        .end(csv);
      return;
    }
    res.writeHead(404).end();
  });
}

const server = createServer([]);

if (process.argv[1] && process.argv[1].endsWith("server.js")) {
  server.listen(process.env.PORT || 3000);
}

export default server;

